SELECT id, session_id AS sessionId, question_id AS questionId, role, content, model_name AS modelName, status, error_message AS errorMessage, latency_ms AS latencyMs, create_time AS createTime FROM ai_chat_message
session_id = #{sessionId} AND user_id = #{userId} AND status = 'success' AND TRIM(content) != '' AND id < #{beforeMessageId}
AND id > #{summaryMessageId}
ORDER BY id ASC LIMIT #{limit}
